package com.hs.jxc.md.service;
import com.hs.jxc.common.api.*;
import com.hs.jxc.common.context.*;
import com.hs.jxc.common.db.DbRows;
import com.hs.jxc.common.audit.AuditWriter;
import com.hs.jxc.common.idempotency.IdempotencyExecutor;
import com.hs.jxc.md.api.MasterProductMaintenanceApi;
import com.hs.jxc.sys.service.AuthorizationService;
import java.math.BigDecimal;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
/** 从原控制器迁入业务主体；旧HTTP及JSON导入委托此服务。 */
@Service
public class MasterProductMaintenanceService implements MasterProductMaintenanceApi {
 private final JdbcTemplate jdbc;private final AuthorizationService auth;private final IdempotencyExecutor idem;private final AuditWriter audit;private final TransactionTemplate tx;
 public MasterProductMaintenanceService(JdbcTemplate jdbc,AuthorizationService auth,IdempotencyExecutor idem,AuditWriter audit,PlatformTransactionManager tm){this.jdbc=jdbc;this.auth=auth;this.idem=idem;this.audit=audit;this.tx=new TransactionTemplate(tm);}
 @SuppressWarnings("unchecked") public Map<String,Object> saveProduct(RequestContext c,Long id,Map<String,Object> b,String key){return (Map<String,Object>)tx.execute(s->{var a=auth.authorizePolicyWrite(c,true);a.require("md:product:edit");if(!a.platformAdmin())throw new ApiException(403,"SYS_FORBIDDEN","全局商品维护需要平台级授权");return idem.execute(c,id==null?"POST":"PUT","/api/v1/md/products"+(id==null?"":"/"+id),key,b,null,()->{Map<String,Object> old=id==null?null:global("md_product",id,true);if(old!=null&&Inputs.version(b)!=n(old,"version"))throw Inputs.conflict();String base=Inputs.required(b,"baseUnit"),code=Inputs.required(b,"productCode"),name=Inputs.required(b,"name");if(old!=null&&!base.equals(old.get("base_unit"))&&jdbc.queryForObject("SELECT count(*) FROM md_product_unit_used WHERE product_id=?",Integer.class,id)>0)throw new ApiException(409,"MD_REFERENCED","已引用商品不能修改基础单位");BigDecimal weight=dimension(b,old,"grossWeight","gross_weight"),volume=dimension(b,old,"volume","volume");long product;if(id==null)product=jdbc.queryForObject("INSERT INTO md_product(product_code,name,base_unit,category_id,brand,spec,status,gross_weight,volume) VALUES(?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,code,name,base,b.get("categoryId")==null?null:Inputs.id(b.get("categoryId")),Inputs.text(b,"brand",""),Inputs.text(b,"spec",""),status(b),weight,volume);else{product=id;jdbc.update("UPDATE md_product SET product_code=?,name=?,base_unit=?,category_id=?,brand=?,spec=?,status=?,gross_weight=?,volume=?,version=version+1 WHERE id=?",code,name,base,b.get("categoryId")==null?null:Inputs.id(b.get("categoryId")),Inputs.text(b,"brand",""),Inputs.text(b,"spec",""),status(b),weight,volume,product);}List<Map<String,Object>> units=new ArrayList<>(maps(b.get("units")));if(units.stream().noneMatch(u->base.equals(u.get("unit"))))units.add(Map.of("unit",base,"factorToBase",BigDecimal.ONE));Set<String> seen=new HashSet<>();for(var unit:units){String u=Inputs.required(unit,"unit");if(!seen.add(u))throw Inputs.bad("单位不能重复");BigDecimal factor=decimal(unit.get("factorToBase"),8);if(factor.signum()<=0||u.equals(base)&&factor.compareTo(BigDecimal.ONE)!=0)throw Inputs.bad("单位换算不合法");var existing=jdbc.queryForList("SELECT factor_to_base FROM md_product_unit WHERE product_id=? AND unit=?",product,u);if(!existing.isEmpty()&&((BigDecimal)existing.getFirst().get("factor_to_base")).compareTo(factor)!=0&&jdbc.queryForObject("SELECT count(*) FROM md_product_unit_used WHERE product_id=? AND unit=?",Integer.class,product,u)>0)throw new ApiException(409,"MD_REFERENCED","历史业务已引用该单位换算");jdbc.update("INSERT INTO md_product_unit(product_id,unit,factor_to_base,is_purchase_default,is_sales_default) VALUES(?,?,?,?,?) ON CONFLICT(product_id,unit) DO UPDATE SET factor_to_base=excluded.factor_to_base,is_purchase_default=excluded.is_purchase_default,is_sales_default=excluded.is_sales_default,version=md_product_unit.version+1",product,u,factor,Boolean.TRUE.equals(unit.get("isPurchaseDefault")),Boolean.TRUE.equals(unit.get("isSalesDefault")));}jdbc.update("DELETE FROM md_product_barcode WHERE product_id=?",product);List<String> barcodes=new ArrayList<>();for(var barcode:maps(b.get("barcodes"))){String bc=Inputs.required(barcode,"barcode"),u=Inputs.required(barcode,"unit");if(!seen.contains(u))throw Inputs.bad("条码的单位未配置");if(barcodes.contains(bc))throw Inputs.bad("条码不能重复");barcodes.add(bc);jdbc.update("INSERT INTO md_product_barcode(product_id,unit,barcode) VALUES(?,?,?)",product,u,bc);}jdbc.update("UPDATE md_product SET barcode_text=? WHERE id=?",String.join(" ",barcodes),product);var result=DbRows.camel(global("md_product",product,false));enrichProduct(result);audit.append(c,"维护全局商品","MD_PRODUCT",product,old,result);return result;},r->{if(!a.platformAdmin())throw ApiException.notFound();});});}
 public Map<String,Object> saveSku(RequestContext c,long productId,Map<String,Object> b,String key){return tx.execute(s->{var a=auth.authorize(c);a.require("md:country-sku:edit");return idem.execute(c,"PUT","/api/v1/md/country-skus/"+Inputs.id(productId),key,b,null,()->{var p=global("md_product",productId,false);var old=jdbc.queryForList("SELECT * FROM md_country_sku WHERE country_id=? AND product_id=? FOR UPDATE",a.requireCountry(),productId);if(!old.isEmpty()&&Inputs.version(b)!=n(old.getFirst(),"version"))throw Inputs.conflict();boolean enabled=b.containsKey("enabled")?Boolean.TRUE.equals(b.get("enabled")):!old.isEmpty()&&"ENABLED".equals(old.getFirst().get("status"));if(enabled&&!"ENABLED".equals(p.get("status")))throw new ApiException(409,"MD_DISABLED","全局商品已停用");jdbc.update("INSERT INTO md_country_sku(country_id,product_id,local_name,tax_category,status) VALUES(?,?,?,?,?) ON CONFLICT(country_id,product_id) DO UPDATE SET local_name=excluded.local_name,tax_category=excluded.tax_category,status=excluded.status,version=md_country_sku.version+1",a.requireCountry(),productId,Inputs.text(b,"localName",old.isEmpty()?"":String.valueOf(old.getFirst().get("local_name"))),Inputs.text(b,"taxCategory",old.isEmpty()?"":String.valueOf(old.getFirst().get("tax_category"))),enabled?"ENABLED":"DISABLED");var result=DbRows.camel(jdbc.queryForMap("SELECT * FROM md_country_sku WHERE country_id=? AND product_id=?",a.requireCountry(),productId));audit.append(c,"维护本国经营SKU","MD_COUNTRY_SKU",n(result,"id"),old,result);return result;},r->{if(!Objects.equals(r.get("countryId"),a.countryId()))throw ApiException.notFound();});});}
 /** 原商品目录与本国经营HTTP、采购候选共用查询主体。 */
 public Map<String,Object> queryProducts(RequestContext c,boolean countrySkus,String keyword,String status,Boolean enabled,int page,int size){return queryProducts(c,countrySkus,keyword,status,enabled,page,size,false);}
 public Map<String,Object> queryProductCandidates(RequestContext c,String keyword,boolean exactCode,int size){return queryProducts(c,false,keyword,"ENABLED",null,1,size,exactCode);}
 private Map<String,Object> queryProducts(RequestContext c,boolean countrySkus,String keyword,String status,Boolean enabled,int page,int size,boolean exactCode){return tx.execute(s->{var a=auth.authorize(c);a.require("md:product:view","md:product:edit");if(page<1||page>1000000||size<1||size>200)throw Inputs.bad("分页参数超出范围");var args=new ArrayList<Object>();String where="TRUE";if(keyword!=null&&!keyword.isBlank()){if(exactCode){where+=" AND lower(btrim(product_code))=lower(btrim(?))";args.add(keyword);}else{where+=" AND (product_code ILIKE ? OR name ILIKE ?)";args.add("%"+keyword+"%");args.add("%"+keyword+"%");}}if(status!=null){where+=" AND status=?";args.add(status);}if(countrySkus&&enabled!=null){where+=" AND "+(enabled?"EXISTS":"NOT EXISTS")+" (SELECT 1 FROM md_country_sku s WHERE s.country_id=? AND s.product_id=md_product.id AND s.status='ENABLED')";args.add(a.requireCountry());}long total=jdbc.queryForObject("SELECT count(*) FROM md_product WHERE "+where,Long.class,args.toArray());args.add(size);args.add((page-1)*size);var rows=jdbc.queryForList("SELECT * FROM md_product WHERE "+where+" ORDER BY id LIMIT ? OFFSET ?",args.toArray()).stream().map(DbRows::camel).toList();for(var row:rows){enrichProduct(row);if(countrySkus){var skus=jdbc.queryForList("SELECT * FROM md_country_sku WHERE country_id=? AND product_id=?",a.requireCountry(),row.get("id"));row.put("productId",row.get("id"));row.put("productStatus",row.get("status"));row.put("enabled",!skus.isEmpty()&&"ENABLED".equals(skus.getFirst().get("status")));row.put("version",skus.isEmpty()?0:skus.getFirst().get("version"));row.put("localName",skus.isEmpty()?"":skus.getFirst().get("local_name"));row.put("taxCategory",skus.isEmpty()?"":skus.getFirst().get("tax_category"));row.put("label",row.get("productCode")+" "+row.get("name"));}}return Map.of("records",rows,"total",total,"page",page,"size",size);});}
 public Map<String,Object> inspect(RequestContext c,long id){return tx.execute(s->{var a=auth.authorize(c);a.requireCountry();a.require("md:product:view");var row=DbRows.camel(global("md_product",Inputs.id(id),false));enrichProduct(row);var skus=jdbc.queryForList("SELECT * FROM md_country_sku WHERE country_id=? AND product_id=?",a.requireCountry(),id);row.put("countrySku",skus.isEmpty()?null:DbRows.camel(skus.getFirst()));return row;});}
 private BigDecimal dimension(Map<String,Object> body,Map<String,Object> old,String field,String column){
  Object value=body.containsKey(field)?body.get(field):old==null?null:old.get(column);
  if(value==null)return null;
  BigDecimal number=Inputs.decimal(value,4,Inputs.PUBLIC_DECIMAL_MAX);
  if(number.signum()<0)throw Inputs.bad(field+"不能为负数");
  return number;
 }
 private Map<String,Object> global(String table,long id,boolean lock){var rows=jdbc.queryForList("SELECT * FROM "+table+" WHERE id=?"+(lock?" FOR UPDATE":""),id);if(rows.isEmpty())throw ApiException.notFound();return rows.getFirst();}
 public void enrichProduct(Map<String,Object> row){long id=n(row,"id");row.put("units",jdbc.queryForList("SELECT * FROM md_product_unit WHERE product_id=? ORDER BY id",id).stream().map(DbRows::camel).toList());row.put("barcodes",jdbc.queryForList("SELECT * FROM md_product_barcode WHERE product_id=? ORDER BY id",id).stream().map(DbRows::camel).toList());}
 private static long n(Map<String,Object> m,String k){return ((Number)m.get(k)).longValue();}
 private static String status(Map<String,Object> b){String s=Inputs.text(b,"status","ENABLED");if(!Set.of("ENABLED","DISABLED").contains(s))throw Inputs.bad("档案状态不合法");return s;}
 private static BigDecimal decimal(Object v,int scale){return Inputs.decimal(v,scale,new BigDecimal("9999999999"));}
 @SuppressWarnings("unchecked") private static List<Map<String,Object>> maps(Object value){if(value==null)return List.of();if(!(value instanceof List<?> list))throw Inputs.bad("明细格式不合法");for(Object item:list)if(!(item instanceof Map))throw Inputs.bad("明细格式不合法");return (List<Map<String,Object>>)value;}
}
